window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-57de8da7f02d7d30"]={"versions": [{"id": "FIG-57de8da7f02d7d30", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionale Software-Architektur / High-Level Logical Component & Data Flow Diagram (AUTOSAR Application Layer, Domain-Übersicht Powertrain/Chassis).</li>\n<li><strong>Technischer Zweck:</strong> Definition der funktionalen Schnittstellen, Drehmomentanforderungs-Ebenen und Regelkreis-Verbindungen zwischen der Fahrwerk-Domäne (<em>Chassis</em>) und dem Antriebsstrang (<em>Powertrain</em>), insbesondere die Integration von Getriebesteuerung (<em>Transmission</em>), Allradmanagement (<em>All Wheel Drive</em>) und Drehmomentkoordination (<em>Power Train Coordinator</em>).</li>\n<li><strong>Systemeinordnung:</strong> AUTOSAR Classic R3.0.7, Standard-Applikationsschnittstellen für den Powertrain-Bereich (<code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Doc-ID 269). Das Diagramm grenzt die Verantwortungsbereiche der Arbeitsgruppen <em>Chassis Application Interfaces Sub-group</em> und <em>Powertrain Application Interfaces Sub-group</em> gegeneinander ab.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Funktionale Domänen & Komponenten (SW-C-Ebene)</p>\n<ol class=\"fig-list\">\n<li><strong>Domäne Chassis (Chassis Application Interfaces Sub-group):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Vehicle Longitudinal Control (VLC)</code>: Längsdynamikregelung (z. B. ACC/Tempomat).</li>\n<li><code>ESC</code> (Electronic Stability Control): Fahrdynamikregelung inkl. Giermomenten- und Traktionsregelung.</li>\n<li><code>Brake System</code>: Reibbremsaktorik, direkt von <code>ESC</code> angesteuert (3 Aktuatorpfade).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Domäne Powertrain (Powertrain Application Interfaces Sub-group):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Power Train Coordinator (PTC)</code>: Zentrale Koordinations-, Priorisierungs-, Optimierungs- und Verteilungsinstanz für Antriebsmomente.</li>\n<li>Enthält die Sub-Entität <code>PT Ratio Coordinator</code> (Übersetzungskoordinator für Fahrstufen/-gänge).</li>\n<li><code>Transmission System</code>: Subsystem zur Wandlung und Verteilung der Antriebsleistung, bestehend aus:</li>\n<li><code>Transmission</code>: Getriebesteuerung (Wandler-/Doppelkupplungs-/Stufenautomat oder CVT).</li>\n<li><code>Transm. System Coord.</code> (Transmission System Coordinator): Lokaler Drehmoment- und Aktor-Koordinator des Getriebe- und Allradstrangs.</li>\n<li><code>All Wheel Drive (AWD)</code>: Allradaktorik-Subkomponenten:</li>\n<li><code>Differential Lock</code> (Quersperren/Längssperren)</li>\n<li><code>Torque Vectoring Axle Transm.</code> (Aktive Momentenverteilung der Achsgetriebe)</li>\n<li><code>Transfer Case</code> (Verteilergetriebe / Längsverteilung)</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signalflüsse (AUTOSAR Sender-Receiver Interfaces)</p>\n<ul class=\"fig-list\">\n<li>*<em>Chassis $\\rightarrow$ Powertrain Coordinator (Ebene: </em>requested powertrain torque at wheel<em>):</em>*</li>\n<li><code>Min. / Max. Total Powertrain torque at wheels requested by VLC</code>: Grenzmomentanforderungen der Längsführung.</li>\n<li><code>Max. / Min. Total Powertrain torque at wheels requested by Stability Control (slow/fast)</code>: Dynamische Eingriffe der Fahrdynamikregelung, differenziert nach Reaktionszeit (schnell via Motor-/Zündungseingriff, langsam via Drosselklappe/Ladedruck).</li>\n<li><code>Powertrain Torque Distribution to Wheels requested by AWD</code>: Radindividuelle Momentenverteilungswünsche aus der AWD/Fahrwerkslogik.</li>\n<li><strong>PT Ratio Coordinator $\\leftrightarrow$ Transmission:</strong></li>\n<li><code>Requested Gear</code> (PT Ratio Coord $\\rightarrow$ Transmission): Sollgang-Vorgabe.</li>\n<li><code>Target Gear, Actual Gear</code> (Transmission $\\rightarrow$ PT Ratio Coord): Schaltabsichts- und Istgang-Rückmeldung.</li>\n<li><strong>Powertrain Coordinator $\\rightarrow$ Transmission System:</strong></li>\n<li><code>Powertrain Torque Distribution To Wheels Requested By PTC</code>: Koordinierte rad-/achsbezogene Soll-Momentenverteilung an den <code>Transm. System Coord.</code></li>\n<li>*<em>Transmission $\\rightarrow$ Subsysteme (Ebene: </em>requested gearbox output torque<em>):</em>*</li>\n<li><code>Gear State, Transmission Torque</code>: Getriebestatus und Ausgangsdrehmoment an <code>Transm. System Coord.</code> und <code>All Wheel Drive</code>.</li>\n<li><strong>Transm. System Coord. $\\leftrightarrow$ All Wheel Drive:</strong></li>\n<li>Bidirektionale Ansteuerung und Rückmeldung an <code>Differential Lock</code>, <code>Torque Vectoring Axle Transm.</code> und <code>Transfer Case</code>.</li>\n<li><strong>Transmission System $\\rightarrow$ Chassis / ESC Feedback:</strong></li>\n<li><code>Actual Powertrain Torque At Wheels</code> bzw. <code>Actual Powertrain Torque At Wheels From Transm. System</code>: Ist-Radmoment-Rückmeldung zur geschlossenen Regelkreisbildung im ESC.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Drehmomentanforderung (Fahrwerk $\\rightarrow$ Koordination):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VLC</code> und <code>ESC</code> senden zyklisch/ereignisgesteuert minimale und maximale Drehmomentgrenzen auf Radebene (<em>requested powertrain torque at wheel</em>). <code>ESC</code>-Eingriffe priorisieren über Fast-/Slow-Pfade gegenüber Fahrerwunsch oder Komfortfunktionen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Übersetzungskoordination (PTC & PT Ratio Coordinator):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PTC</code> fusioniert, optimiert und priorisiert die Drehmomentgrenzen.</li>\n<li><code>PT Ratio Coordinator</code> bestimmt die Zielübersetzung und triggert <code>Requested Gear</code> an <code>Transmission</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Getriebestatus & Drehmomentwandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Transmission</code> führt den Gangwechsel aus und meldet Übergangszustände (<code>Target Gear</code>, <code>Gear State</code>) sowie das gewandelte Getriebeausgangsmoment (<code>Transmission Torque</code>) an <code>Transm. System Coord.</code> und <code>All Wheel Drive</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verteilung auf die Aktuatoren (AWD):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Basierend auf der koordinierten Momentenverteilung des PTC und dem Getriebeistzustand berechnet <code>Transm. System Coord.</code> Stellgrößen für Sperren (<code>Differential Lock</code>), Momentenvektorierung (<code>Torque Vectoring Axle Transm.</code>) und Längskraftverteilung (<code>Transfer Case</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkopplungsschleife (Feedback Loop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das resultierende Rad-Istmoment (<code>Actual Powertrain Torque At Wheels</code>) wird ermittelt und über die Domänengrenze an das <code>ESC</code> zurückgespeist, um Giermomenten- und Schlupfregelungen abzugleichen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normativer Status (AUTOSAR R3.0.7):</strong></li>\n<li>Das Diagramm ist gemäß Spezifikationshinweis rein illustrativ. Bei Diskrepanzen zwischen dieser Darstellung und der <em>Master Table of Interfaces</em> (Doc ID 269) ist zwingend die <strong>Master Table</strong> verbindlich.</li>\n<li><strong>Konsequenzen für SW-C- und RTE-Entwickler:</strong></li>\n<li><strong>Referenzebenen-Transformation:</strong> SW-Cs müssen strikt zwischen Drehmomentgrößen an den Rädern (<em>powertrain torque at wheel</em>) und Drehmomentgrößen am Getriebeabtrieb (<em>gearbox output torque</em>) unterscheiden. Die physikalische Skalierung (Einheit $\\text{Nm}$, Radien, Übersetzungsverhältnisse $i_{\\text{gear}} \\cdot i_{\\text{axle}}$) muss in den Port-Interfaces konsistent über <code>ApplicationDataType</code> bzw. <code>CompuMethod</code> parametriert werden.</li>\n<li><strong>Timing & Pfadlatenzen:</strong> Die Unterscheidung in <code>slow</code> und <code>fast</code> Anforderungen aus dem ESC erfordert getrennte Task-Perioden im OS (z. B. 10 ms oder ereignisgetriggert für ESC Fast vs. 20–50 ms für VLC/PTC).</li>\n<li><strong>Fehlerbehandlung & Degradation:</strong> Schaltausfälle (<code>Transmission</code> meldet abweichenden <code>Gear State</code>) oder Fehler in den Allrad-Aktoren erfordern standardisierte Ersatzwerte bzw. Init-Werte im RTE-Buffer sowie Dem-Event-Meldungen, da das ESC bei fehlerhafter Momenten-Rückmeldung in den Passiv-/Warnmodus übergehen muss.</li>\n</ul>"}, {"id": "FIG-5e59feb7a2195a08", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionale Software-Architektur / High-Level Logical Component & Data Flow Diagram (AUTOSAR Application Layer, Domain-Übersicht Powertrain/Chassis).</li>\n<li><strong>Technischer Zweck:</strong> Definition der funktionalen Schnittstellen, Drehmomentanforderungs-Ebenen und Regelkreis-Verbindungen zwischen der Fahrwerk-Domäne (<em>Chassis</em>) und dem Antriebsstrang (<em>Powertrain</em>), insbesondere die Integration von Getriebesteuerung (<em>Transmission</em>), Allradmanagement (<em>All Wheel Drive</em>) und Drehmomentkoordination (<em>Power Train Coordinator</em>).</li>\n<li><strong>Systemeinordnung:</strong> AUTOSAR Classic R3.0.7, Standard-Applikationsschnittstellen für den Powertrain-Bereich (<code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Doc-ID 269). Das Diagramm grenzt die Verantwortungsbereiche der Arbeitsgruppen <em>Chassis Application Interfaces Sub-group</em> und <em>Powertrain Application Interfaces Sub-group</em> gegeneinander ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Funktionale Domänen & Komponenten (SW-C-Ebene)</p>\n<ol class=\"fig-list\">\n<li><strong>Domäne Chassis (Chassis Application Interfaces Sub-group):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Vehicle Longitudinal Control (VLC)</code>: Längsdynamikregelung (z. B. ACC/Tempomat).</li>\n<li><code>ESC</code> (Electronic Stability Control): Fahrdynamikregelung inkl. Giermomenten- und Traktionsregelung.</li>\n<li><code>Brake System</code>: Reibbremsaktorik, direkt von <code>ESC</code> angesteuert (3 Aktuatorpfade).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Domäne Powertrain (Powertrain Application Interfaces Sub-group):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Power Train Coordinator (PTC)</code>: Zentrale Koordinations-, Priorisierungs-, Optimierungs- und Verteilungsinstanz für Antriebsmomente.</li>\n<li>Enthält die Sub-Entität <code>PT Ratio Coordinator</code> (Übersetzungskoordinator für Fahrstufen/-gänge).</li>\n<li><code>Transmission System</code>: Subsystem zur Wandlung und Verteilung der Antriebsleistung, bestehend aus:</li>\n<li><code>Transmission</code>: Getriebesteuerung (Wandler-/Doppelkupplungs-/Stufenautomat oder CVT).</li>\n<li><code>Transm. System Coord.</code> (Transmission System Coordinator): Lokaler Drehmoment- und Aktor-Koordinator des Getriebe- und Allradstrangs.</li>\n<li><code>All Wheel Drive (AWD)</code>: Allradaktorik-Subkomponenten:</li>\n<li><code>Differential Lock</code> (Quersperren/Längssperren)</li>\n<li><code>Torque Vectoring Axle Transm.</code> (Aktive Momentenverteilung der Achsgetriebe)</li>\n<li><code>Transfer Case</code> (Verteilergetriebe / Längsverteilung)</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signalflüsse (AUTOSAR Sender-Receiver Interfaces)</p>\n<ul class=\"fig-list\">\n<li>*<em>Chassis $\\rightarrow$ Powertrain Coordinator (Ebene: </em>requested powertrain torque at wheel<em>):</em>*</li>\n<li><code>Min. / Max. Total Powertrain torque at wheels requested by VLC</code>: Grenzmomentanforderungen der Längsführung.</li>\n<li><code>Max. / Min. Total Powertrain torque at wheels requested by Stability Control (slow/fast)</code>: Dynamische Eingriffe der Fahrdynamikregelung, differenziert nach Reaktionszeit (schnell via Motor-/Zündungseingriff, langsam via Drosselklappe/Ladedruck).</li>\n<li><code>Powertrain Torque Distribution to Wheels requested by AWD</code>: Radindividuelle Momentenverteilungswünsche aus der AWD/Fahrwerkslogik.</li>\n<li><strong>PT Ratio Coordinator $\\leftrightarrow$ Transmission:</strong></li>\n<li><code>Requested Gear</code> (PT Ratio Coord $\\rightarrow$ Transmission): Sollgang-Vorgabe.</li>\n<li><code>Target Gear, Actual Gear</code> (Transmission $\\rightarrow$ PT Ratio Coord): Schaltabsichts- und Istgang-Rückmeldung.</li>\n<li><strong>Powertrain Coordinator $\\rightarrow$ Transmission System:</strong></li>\n<li><code>Powertrain Torque Distribution To Wheels Requested By PTC</code>: Koordinierte rad-/achsbezogene Soll-Momentenverteilung an den <code>Transm. System Coord.</code></li>\n<li>*<em>Transmission $\\rightarrow$ Subsysteme (Ebene: </em>requested gearbox output torque<em>):</em>*</li>\n<li><code>Gear State, Transmission Torque</code>: Getriebestatus und Ausgangsdrehmoment an <code>Transm. System Coord.</code> und <code>All Wheel Drive</code>.</li>\n<li><strong>Transm. System Coord. $\\leftrightarrow$ All Wheel Drive:</strong></li>\n<li>Bidirektionale Ansteuerung und Rückmeldung an <code>Differential Lock</code>, <code>Torque Vectoring Axle Transm.</code> und <code>Transfer Case</code>.</li>\n<li><strong>Transmission System $\\rightarrow$ Chassis / ESC Feedback:</strong></li>\n<li><code>Actual Powertrain Torque At Wheels</code> bzw. <code>Actual Powertrain Torque At Wheels From Transm. System</code>: Ist-Radmoment-Rückmeldung zur geschlossenen Regelkreisbildung im ESC.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Drehmomentanforderung (Fahrwerk $\\rightarrow$ Koordination):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VLC</code> und <code>ESC</code> senden zyklisch/ereignisgesteuert minimale und maximale Drehmomentgrenzen auf Radebene (<em>requested powertrain torque at wheel</em>). <code>ESC</code>-Eingriffe priorisieren über Fast-/Slow-Pfade gegenüber Fahrerwunsch oder Komfortfunktionen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Übersetzungskoordination (PTC & PT Ratio Coordinator):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PTC</code> fusioniert, optimiert und priorisiert die Drehmomentgrenzen.</li>\n<li><code>PT Ratio Coordinator</code> bestimmt die Zielübersetzung und triggert <code>Requested Gear</code> an <code>Transmission</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Getriebestatus & Drehmomentwandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Transmission</code> führt den Gangwechsel aus und meldet Übergangszustände (<code>Target Gear</code>, <code>Gear State</code>) sowie das gewandelte Getriebeausgangsmoment (<code>Transmission Torque</code>) an <code>Transm. System Coord.</code> und <code>All Wheel Drive</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verteilung auf die Aktuatoren (AWD):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Basierend auf der koordinierten Momentenverteilung des PTC und dem Getriebeistzustand berechnet <code>Transm. System Coord.</code> Stellgrößen für Sperren (<code>Differential Lock</code>), Momentenvektorierung (<code>Torque Vectoring Axle Transm.</code>) und Längskraftverteilung (<code>Transfer Case</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkopplungsschleife (Feedback Loop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das resultierende Rad-Istmoment (<code>Actual Powertrain Torque At Wheels</code>) wird ermittelt und über die Domänengrenze an das <code>ESC</code> zurückgespeist, um Giermomenten- und Schlupfregelungen abzugleichen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normativer Status (AUTOSAR R3.0.7):</strong></li>\n<li>Das Diagramm ist gemäß Spezifikationshinweis rein illustrativ. Bei Diskrepanzen zwischen dieser Darstellung und der <em>Master Table of Interfaces</em> (Doc ID 269) ist zwingend die <strong>Master Table</strong> verbindlich.</li>\n<li><strong>Konsequenzen für SW-C- und RTE-Entwickler:</strong></li>\n<li><strong>Referenzebenen-Transformation:</strong> SW-Cs müssen strikt zwischen Drehmomentgrößen an den Rädern (<em>powertrain torque at wheel</em>) und Drehmomentgrößen am Getriebeabtrieb (<em>gearbox output torque</em>) unterscheiden. Die physikalische Skalierung (Einheit $\\text{Nm}$, Radien, Übersetzungsverhältnisse $i_{\\text{gear}} \\cdot i_{\\text{axle}}$) muss in den Port-Interfaces konsistent über <code>ApplicationDataType</code> bzw. <code>CompuMethod</code> parametriert werden.</li>\n<li><strong>Timing & Pfadlatenzen:</strong> Die Unterscheidung in <code>slow</code> und <code>fast</code> Anforderungen aus dem ESC erfordert getrennte Task-Perioden im OS (z. B. 10 ms oder ereignisgetriggert für ESC Fast vs. 20–50 ms für VLC/PTC).</li>\n<li><strong>Fehlerbehandlung & Degradation:</strong> Schaltausfälle (<code>Transmission</code> meldet abweichenden <code>Gear State</code>) oder Fehler in den Allrad-Aktoren erfordern standardisierte Ersatzwerte bzw. Init-Werte im RTE-Buffer sowie Dem-Event-Meldungen, da das ESC bei fehlerhafter Momenten-Rückmeldung in den Passiv-/Warnmodus übergehen muss.</li>\n</ul>"}, {"id": "FIG-d265deaead131ed8", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionale Software-Architektur / High-Level Logical Component & Data Flow Diagram (AUTOSAR Application Layer, Domain-Übersicht Powertrain/Chassis).</li>\n<li><strong>Technischer Zweck:</strong> Definition der funktionalen Schnittstellen, Drehmomentanforderungs-Ebenen und Regelkreis-Verbindungen zwischen der Fahrwerk-Domäne (<em>Chassis</em>) und dem Antriebsstrang (<em>Powertrain</em>), insbesondere die Integration von Getriebesteuerung (<em>Transmission</em>), Allradmanagement (<em>All Wheel Drive</em>) und Drehmomentkoordination (<em>Power Train Coordinator</em>).</li>\n<li><strong>Systemeinordnung:</strong> AUTOSAR Classic R3.0.7, Standard-Applikationsschnittstellen für den Powertrain-Bereich (<code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Doc-ID 269). Das Diagramm grenzt die Verantwortungsbereiche der Arbeitsgruppen <em>Chassis Application Interfaces Sub-group</em> und <em>Powertrain Application Interfaces Sub-group</em> gegeneinander ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Funktionale Domänen & Komponenten (SW-C-Ebene)</p>\n<ol class=\"fig-list\">\n<li><strong>Domäne Chassis (Chassis Application Interfaces Sub-group):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Vehicle Longitudinal Control (VLC)</code>: Längsdynamikregelung (z. B. ACC/Tempomat).</li>\n<li><code>ESC</code> (Electronic Stability Control): Fahrdynamikregelung inkl. Giermomenten- und Traktionsregelung.</li>\n<li><code>Brake System</code>: Reibbremsaktorik, direkt von <code>ESC</code> angesteuert (3 Aktuatorpfade).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Domäne Powertrain (Powertrain Application Interfaces Sub-group):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Power Train Coordinator (PTC)</code>: Zentrale Koordinations-, Priorisierungs-, Optimierungs- und Verteilungsinstanz für Antriebsmomente.</li>\n<li>Enthält die Sub-Entität <code>PT Ratio Coordinator</code> (Übersetzungskoordinator für Fahrstufen/-gänge).</li>\n<li><code>Transmission System</code>: Subsystem zur Wandlung und Verteilung der Antriebsleistung, bestehend aus:</li>\n<li><code>Transmission</code>: Getriebesteuerung (Wandler-/Doppelkupplungs-/Stufenautomat oder CVT).</li>\n<li><code>Transm. System Coord.</code> (Transmission System Coordinator): Lokaler Drehmoment- und Aktor-Koordinator des Getriebe- und Allradstrangs.</li>\n<li><code>All Wheel Drive (AWD)</code>: Allradaktorik-Subkomponenten:</li>\n<li><code>Differential Lock</code> (Quersperren/Längssperren)</li>\n<li><code>Torque Vectoring Axle Transm.</code> (Aktive Momentenverteilung der Achsgetriebe)</li>\n<li><code>Transfer Case</code> (Verteilergetriebe / Längsverteilung)</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signalflüsse (AUTOSAR Sender-Receiver Interfaces)</p>\n<ul class=\"fig-list\">\n<li>*<em>Chassis $\\rightarrow$ Powertrain Coordinator (Ebene: </em>requested powertrain torque at wheel<em>):</em>*</li>\n<li><code>Min. / Max. Total Powertrain torque at wheels requested by VLC</code>: Grenzmomentanforderungen der Längsführung.</li>\n<li><code>Max. / Min. Total Powertrain torque at wheels requested by Stability Control (slow/fast)</code>: Dynamische Eingriffe der Fahrdynamikregelung, differenziert nach Reaktionszeit (schnell via Motor-/Zündungseingriff, langsam via Drosselklappe/Ladedruck).</li>\n<li><code>Powertrain Torque Distribution to Wheels requested by AWD</code>: Radindividuelle Momentenverteilungswünsche aus der AWD/Fahrwerkslogik.</li>\n<li><strong>PT Ratio Coordinator $\\leftrightarrow$ Transmission:</strong></li>\n<li><code>Requested Gear</code> (PT Ratio Coord $\\rightarrow$ Transmission): Sollgang-Vorgabe.</li>\n<li><code>Target Gear, Actual Gear</code> (Transmission $\\rightarrow$ PT Ratio Coord): Schaltabsichts- und Istgang-Rückmeldung.</li>\n<li><strong>Powertrain Coordinator $\\rightarrow$ Transmission System:</strong></li>\n<li><code>Powertrain Torque Distribution To Wheels Requested By PTC</code>: Koordinierte rad-/achsbezogene Soll-Momentenverteilung an den <code>Transm. System Coord.</code></li>\n<li>*<em>Transmission $\\rightarrow$ Subsysteme (Ebene: </em>requested gearbox output torque<em>):</em>*</li>\n<li><code>Gear State, Transmission Torque</code>: Getriebestatus und Ausgangsdrehmoment an <code>Transm. System Coord.</code> und <code>All Wheel Drive</code>.</li>\n<li><strong>Transm. System Coord. $\\leftrightarrow$ All Wheel Drive:</strong></li>\n<li>Bidirektionale Ansteuerung und Rückmeldung an <code>Differential Lock</code>, <code>Torque Vectoring Axle Transm.</code> und <code>Transfer Case</code>.</li>\n<li><strong>Transmission System $\\rightarrow$ Chassis / ESC Feedback:</strong></li>\n<li><code>Actual Powertrain Torque At Wheels</code> bzw. <code>Actual Powertrain Torque At Wheels From Transm. System</code>: Ist-Radmoment-Rückmeldung zur geschlossenen Regelkreisbildung im ESC.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Drehmomentanforderung (Fahrwerk $\\rightarrow$ Koordination):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VLC</code> und <code>ESC</code> senden zyklisch/ereignisgesteuert minimale und maximale Drehmomentgrenzen auf Radebene (<em>requested powertrain torque at wheel</em>). <code>ESC</code>-Eingriffe priorisieren über Fast-/Slow-Pfade gegenüber Fahrerwunsch oder Komfortfunktionen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Übersetzungskoordination (PTC & PT Ratio Coordinator):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PTC</code> fusioniert, optimiert und priorisiert die Drehmomentgrenzen.</li>\n<li><code>PT Ratio Coordinator</code> bestimmt die Zielübersetzung und triggert <code>Requested Gear</code> an <code>Transmission</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Getriebestatus & Drehmomentwandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Transmission</code> führt den Gangwechsel aus und meldet Übergangszustände (<code>Target Gear</code>, <code>Gear State</code>) sowie das gewandelte Getriebeausgangsmoment (<code>Transmission Torque</code>) an <code>Transm. System Coord.</code> und <code>All Wheel Drive</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verteilung auf die Aktuatoren (AWD):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Basierend auf der koordinierten Momentenverteilung des PTC und dem Getriebeistzustand berechnet <code>Transm. System Coord.</code> Stellgrößen für Sperren (<code>Differential Lock</code>), Momentenvektorierung (<code>Torque Vectoring Axle Transm.</code>) und Längskraftverteilung (<code>Transfer Case</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkopplungsschleife (Feedback Loop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das resultierende Rad-Istmoment (<code>Actual Powertrain Torque At Wheels</code>) wird ermittelt und über die Domänengrenze an das <code>ESC</code> zurückgespeist, um Giermomenten- und Schlupfregelungen abzugleichen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normativer Status (AUTOSAR R3.0.7):</strong></li>\n<li>Das Diagramm ist gemäß Spezifikationshinweis rein illustrativ. Bei Diskrepanzen zwischen dieser Darstellung und der <em>Master Table of Interfaces</em> (Doc ID 269) ist zwingend die <strong>Master Table</strong> verbindlich.</li>\n<li><strong>Konsequenzen für SW-C- und RTE-Entwickler:</strong></li>\n<li><strong>Referenzebenen-Transformation:</strong> SW-Cs müssen strikt zwischen Drehmomentgrößen an den Rädern (<em>powertrain torque at wheel</em>) und Drehmomentgrößen am Getriebeabtrieb (<em>gearbox output torque</em>) unterscheiden. Die physikalische Skalierung (Einheit $\\text{Nm}$, Radien, Übersetzungsverhältnisse $i_{\\text{gear}} \\cdot i_{\\text{axle}}$) muss in den Port-Interfaces konsistent über <code>ApplicationDataType</code> bzw. <code>CompuMethod</code> parametriert werden.</li>\n<li><strong>Timing & Pfadlatenzen:</strong> Die Unterscheidung in <code>slow</code> und <code>fast</code> Anforderungen aus dem ESC erfordert getrennte Task-Perioden im OS (z. B. 10 ms oder ereignisgetriggert für ESC Fast vs. 20–50 ms für VLC/PTC).</li>\n<li><strong>Fehlerbehandlung & Degradation:</strong> Schaltausfälle (<code>Transmission</code> meldet abweichenden <code>Gear State</code>) oder Fehler in den Allrad-Aktoren erfordern standardisierte Ersatzwerte bzw. Init-Werte im RTE-Buffer sowie Dem-Event-Meldungen, da das ESC bei fehlerhafter Momenten-Rückmeldung in den Passiv-/Warnmodus übergehen muss.</li>\n</ul>"}], "trans": [{"from": "FIG-57de8da7f02d7d30", "to": "FIG-5e59feb7a2195a08", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5e59feb7a2195a08", "to": "FIG-d265deaead131ed8", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
